const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const taiwan = ee.Geometry.Rectangle([119.5, 21.5, 122.5, 25.5]);
  const band = 'tropospheric_NO2_column_number_density';

  // Period 1: February 10-25, 2020
  const startDate1 = '2020-02-10';
  const endDate1 = '2020-02-25';

  // Period 2: April 20-May 12, 2020
  const startDate2 = '2020-04-20';
  const endDate2 = '2020-05-12';

  // 2. Data Acquisition & Check
  const s5p_collection = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2')
    .select([band, 'qa_value'])
    .filterBounds(taiwan);

  const collection1 = s5p_collection.filterDate(startDate1, endDate1);
  const collection2 = s5p_collection.filterDate(startDate2, endDate2);

  const size1 = collection1.size().getInfo();
  const size2 = collection2.size().getInfo();

  if (size1 === 0 || size2 === 0) {
    console.log(`Image count for Feb 2020: ${size1}`);
    console.log(`Image count for Apr-May 2020: ${size2}`);
    console.log('C1: Empty Collection');
    return;
  }
  console.log(`Image count for Feb 2020: ${size1}`);
  console.log(`Image count for Apr-May 2020: ${size2}`);

  // 3. Processing: Create mean composites with QA mask
  const maskClouds = function(image) {
    return image.updateMask(image.select('qa_value').gt(0.75));
  };
  const image1 = collection1.map(maskClouds).mean();
  const image2 = collection2.map(maskClouds).mean();

  // 4. Calculation
  const reducer = ee.Reducer.mean().combine({
    reducer2: ee.Reducer.count(),
    sharedInputs: true
  });

  const stats1 = image1.reduceRegion({
    reducer: reducer,
    geometry: taiwan,
    scale: 5000,
    maxPixels: 1e9
  });

  const stats2 = image2.reduceRegion({
    reducer: reducer,
    geometry: taiwan,
    scale: 5000,
    maxPixels: 1e9
  });

  const mean1 = stats1.get(band + '_mean').getInfo();
  const count1 = stats1.get(band + '_count').getInfo();
  const mean2 = stats2.get(band + '_mean').getInfo();
  const count2 = stats2.get(band + '_count').getInfo();

  // 5. Validation & Final Answer
  if (count1 === 0 || count2 === 0) {
    console.log(`Valid pixel count Feb 2020: ${count1}`);
    console.log(`Valid pixel count Apr-May 2020: ${count2}`);
    console.log('C2: No Valid Pixels');
    return;
  }
  console.log(`Valid pixel count Feb 2020: ${count1}`);
  console.log(`Valid pixel count Apr-May 2020: ${count2}`);

  if (mean1 === null || mean2 === null) {
      console.log(`Feb 2020 Mean NO2: ${mean1}`);
      console.log(`Apr-May 2020 Mean NO2: ${mean2}`);
      console.log('C3: Calculation Failure');
      return;
  }

  // Values are in mol/m^2. Multiply by 1e6 for a more readable micromol/m^2.
  const mean1_umol = mean1 * 1e6;
  const mean2_umol = mean2 * 1e6;

  console.log(`Feb 2020 Mean NO2 (umol/m^2): ${mean1_umol.toFixed(2)}`);
  console.log(`Apr-May 2020 Mean NO2 (umol/m^2): ${mean2_umol.toFixed(2)}`);

  if (mean2 > mean1) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(err => {
    console.error(err);
    console.log('D');
});
